              "அரைப்புள்ளி (Semicolon - ;): ஒரே எழுவாயில் பல சிறு தொடர்கள் தொடர்ந்து வரும்போது இடையில் வரும்.",
              "முக்கால்புள்ளி (Colon - :): மேற்கோள் அல்லது விவரப்பட்டியலைத் தொடங்குமுன் வரும்.",
              "முற்றுப்புள்ளி (Full stop - .): ஒரு கருத்து அல்லது தொடர் முழுமை பெறும்போது இறுதியில் வரும்.",
